input.command:
cd /tmp && cat > runall.py <<'EOF'
import json,collections,numpy as np,ecglib as E,report,traceback
pat=json.load(open('patients.json'))['resources']
living={p['id'] for p in pat if not p.get('deceasedDateTime')}
ecgs=json.load(open('ecgall.json'))['ecgs']
by=collections.defaultdict(list)
for x in ecgs:
    if x['patient'] in living: by[x['patient']].append(x)
res={}
for p,xs in by.items():
    for x in sorted(xs,key=lambda y:y['time']):
        eid=x['ecg']
        try:
            out,M,Xf,rp=report.analyze(eid,verbose=False)
            a=out['a']
            atr=E.atrial_features(Xf,rp,M,a)
            pc=E.p_consistency(Xf,rp)
            on,off=out['on'],out['off']
            areas={n:float(M[on:off,i].sum()) for i,n in enumerate(E.LEADS)}
            peaks={n:[float(M[on:off,i].max()),float(M[on:off,i].min())] for i,n in enumerate(E.LEADS)}
            out['rr']=[float(v) for v in out['rr']]
            out.update(pat=p,time=x['time'],atr=atr,pcons=pc,areas=areas,peaks=peaks)
            res[eid]=out
        except Exception as ex:
            print('ERR',eid,ex); traceback.print_exc()
json.dump(res,open('ecgfeat.json','w'),indent=0)
print(len(res))
EOF
python3 runall.py 2>&1 | tail -20

